#!/usr/bin/env Rscript
# Reader-facing workbook (supplementary table) of the WGCNA modules, supermodules and their labels, for the primary
# analysis (all-protein median centring) and the sensitivity analysis (complete-case median centring): every label with
# the GO terms it names, the rules that form labels, the grouping of GO terms into signals, every significant GO term with
# its proteins, module membership with kME, and leave-one-animal-out stability. Every number, table and reader note is
# computed here from the saved networks and the label tables, with checks that stop the build when a statement no longer
# fits the data; written by hand are only the module label wording (labels.tsv), the method text and the reader-note
# templates. The label history goes to a separate internal file, not to the supplement.
# Writes results/reviewer_audit/normalisation_choice_2026-10-21/workbooks/Proteomics_WGCNA_module_labels.xlsx and
# Proteomics_WGCNA_label_history.xlsx (internal).
#
# Sources: each network's model state (primary: the worktree Analysis/proteomics_original; sensitivity: this working tree),
# the scripted label classes (annotation_review/rule_based/, label_modules_by_rule.R), the wording (rule_based/labels.tsv;
# supermodule labels generated by derive_supermodule_labels.R), the named-term table and label checks (label_terms.csv,
# label_form_check.csv; check_rule_labels.R), the change log (annotation_review/label_changes_2026-10-23.csv; internal file
# only) and the leave-one-animal-out rebuilds (validation/wgcna_builds). Gene symbols are the official mouse symbols of the
# Entrez IDs (org.Mm.eg.db); software versions come from renv.lock and must match the installed packages.
# USAGE  Rscript tools/normalisation_review/build_wgcna_labels_workbook.R      (working directory: repo root; run
#        derive_supermodule_labels.R and check_rule_labels.R first)

source(file.path("R", "paths.R"))
suppressPackageStartupMessages({ library(openxlsx); library(dplyr); library(readr); library(tidyr) })
source(repo_path("R", "review_workbook_style.R"))
ORIG <- Sys.getenv("PROTEOMICS_ORIGINAL_ROOT", unset = if (dir.exists("R:/results")) "R:" else
  "S:/Lab_Member/Tobi/Experiments/Exp9_Social-Stress/Analysis/proteomics_original")
REV <- path_results("reviewer_audit", "normalisation_choice_2026-10-21")
ANN <- file.path(REV, "annotation_review"); RB <- file.path(ANN, "rule_based"); BUILDS <- file.path(REV, "validation", "wgcna_builds")
OUT <- file.path(REV, "workbooks"); dir.create(OUT, recursive = TRUE, showWarnings = FALSE)
rd <- function(f) read_csv(f, show_col_types = FALSE, guess_max = 1e5)
DATASETS <- c(neuron_neuropil = "Neuropil", neuron_soma = "Soma", microglia = "Microglia-enriched")
CENT <- c(original = "Primary", new = "Sensitivity")   # primary: all-protein median centring; sensitivity: complete-case median centring
WORD <- c(original = "primary", new = "sensitivity")
ANIMALS <- c("A0003", "A111", "A127", "A129", "A135", "A139", "A755", "A764", "A765")
STATE <- list(original = function(ds) file.path(ORIG, "results", "wgcna", "build_wgcna_modules", ds, "models", "wgcna_final_model_state.rds"),
              new = function(ds) file.path("results", "wgcna", "build_wgcna_modules", ds, "models", "wgcna_final_model_state.rds"))
EST <- c(original = "original_all_observed", new = "new_complete_case")
is_module <- function(m) !is.na(m) & !grepl("grey|unassigned|m00", m)
state_evidence <- function(s) paste(s$parameters$gene_annotation_contract_version %||% "legacy_uniprot_gene_name",
                                    s$parameters$module_go_min_gs_size %||% 10L, s$parameters$module_go_max_gs_size %||% 500L, sep = " / ")
evidence_seen <- character()
short <- function(m) sub("^WGCNA_", "", m)
lab_c <- function(v) unname(CENT[v]); lab_ds <- function(d) unname(DATASETS[d])
ord <- function(df) df |> arrange(factor(version, names(CENT)), factor(dataset, names(DATASETS)))
fq <- function(q) ifelse(is.na(q), NA_character_, ifelse(q >= 0.001, sprintf("%.3f", q), sprintf("%.1e", q)))
SCI <- createStyle(numFmt = "0.0E+00", halign = "center"); D2 <- createStyle(numFmt = "0.00", halign = "center")
D1 <- createStyle(numFmt = "0.0", halign = "center"); D3 <- createStyle(numFmt = "0.000", halign = "center")
HI <- createStyle(bgFill = "#DCEBF5", textDecoration = "bold")
sym_of <- function(entrez) {   # official mouse gene symbols
  e <- unique(na.omit(as.character(entrez))); if (!length(e)) return(setNames(character(), character()))
  suppressMessages(AnnotationDbi::mapIds(org.Mm.eg.db::org.Mm.eg.db, keys = e, column = "SYMBOL", keytype = "ENTREZID", multiVals = "first"))
}

rules <- yaml::read_yaml(file.path(RB, "rules.yml"))
rmod <- rd(file.path(RB, "module_rule_classes.csv")); rsm <- rd(file.path(RB, "supermodule_rule_classes.csv"))
rsig <- rd(file.path(RB, "module_signals.csv")); rsig_all <- rd(file.path(RB, "module_signals_all_ontologies.csv")); rterm <- rd(file.path(RB, "signal_terms.csv"))
lab <- read_tsv(file.path(RB, "labels.tsv"), show_col_types = FALSE, quote = "")
chk <- rd(file.path(RB, "label_form_check.csv")); lt <- rd(file.path(RB, "label_terms.csv")); chg <- rd(file.path(ANN, "label_changes_2026-10-23.csv"))
if (any(file.mtime(file.path(RB, c("label_form_check.csv", "label_terms.csv"))) < file.mtime(file.path(RB, "labels.tsv"))))
  stop("labels.tsv is newer than the label check: run check_rule_labels.R first.", call. = FALSE)
stopifnot(nrow(lab) == nrow(chk), all(chk$problem %in% c(NA, "")), !anyNA(lt$term_id))
mlab <- lab |> filter(level == "module") |> select(version, dataset, ModuleID = entity_id, label)
slab <- lab |> filter(level == "supermodule") |> select(version, dataset, SupermoduleID = entity_id, label)
sm_of <- rsm |> select(version, dataset, SupermoduleID, member_modules) |> separate_rows(member_modules, sep = ";") |> rename(ModuleID = member_modules)

# ----------------------------------------------------------------------------------- per network: state, GO, proteins, stability
ari <- function(a, b) {
  ids <- intersect(names(a), names(b)); a <- a[ids]; b <- b[ids]
  tab <- table(a, b); n <- sum(tab); c2 <- function(v) sum(v * (v - 1) / 2)
  sij <- c2(tab); sa <- c2(rowSums(tab)); sb <- c2(colSums(tab)); e <- sa * sb / (n * (n - 1) / 2)
  (sij - e) / ((sa + sb) / 2 - e)
}
jac <- function(a, b) if (!length(a) && !length(b)) NA_real_ else length(intersect(a, b)) / length(union(a, b))
stability_per_animal <- function(ds, v, long) {   # as label_modules_by_rule.R, keeping the value for each left-out animal
  prefixes <- c(if (v == "original") sprintf("%s_archived_original", ds), sprintf("%s_%s", ds, EST[[v]]))
  pipe <- setNames(ifelse(is_module(long$ModuleID), long$ModuleID, "grey"), long$ProteinGroupID)
  for (cand in prefixes) {
    f_full <- file.path(BUILDS, paste0(cand, "_full.rds")); if (!file.exists(f_full)) next
    full <- readRDS(f_full); a <- ari(full, pipe); if (a < rules$rebuild_ari) next
    map <- tibble(pg = names(full), colour = unname(full)) |> inner_join(transmute(long, pg = ProteinGroupID, ModuleID), by = "pg") |>
      filter(colour != "grey", is_module(ModuleID)) |> count(colour, ModuleID) |> group_by(colour) |> slice_max(n, n = 1, with_ties = FALSE) |> ungroup()
    files <- list.files(BUILDS, pattern = sprintf("^%s_loao_A[0-9]+[.]rds$", cand), full.names = TRUE)
    lo_all <- setNames(lapply(files, readRDS), sub("^.*_loao_(A[0-9]+)[.]rds$", "\\1", files))
    tab <- bind_rows(lapply(seq_len(nrow(map)), function(i) {
      mod_pg <- names(full)[full == map$colour[i]]
      js <- vapply(lo_all, function(lo) {
        shared <- intersect(mod_pg, names(lo)); if (!length(shared)) return(NA_real_)
        cc <- setdiff(unique(lo[shared]), "grey"); if (!length(cc)) return(0)
        max(vapply(cc, function(x) jac(shared, intersect(names(lo)[lo == x], names(full))), numeric(1)))
      }, numeric(1))
      tibble(ModuleID = map$ModuleID[i], animal = names(js), jaccard = unname(js))
    }))
    return(list(tab = tab, ari = a))
  }
  list(tab = tibble(ModuleID = character(), animal = character(), jaccard = numeric()), ari = NA_real_)
}
nets <- list(); go_raw <- list(); core_all <- list(); prot_all <- list(); stab_all <- list(); hubs_all <- list()
for (v in names(CENT)) for (ds in names(DATASETS)) {
  s <- readRDS(STATE[[v]](ds)); long <- as.data.frame(s$WGCNA_modules_long); p <- s$parameters
  evidence_seen <- unique(c(evidence_seen, state_evidence(s)))
  if (length(evidence_seen) > 1L) stop("The two analyses carry different gene annotation or GO limits (", paste(evidence_seen, collapse = " vs "),
                                       "); regenerate both with the same code before comparing them.", call. = FALSE)
  g <- as.data.frame(s$GO_enrichment) |> filter(is_module(ModuleID))
  go <- g |> filter(ModuleProteinSetType == "all") |> mutate(q_net = stats::p.adjust(pvalue, "BH"))   # BH across all modules and ontologies
  stopifnot(max(abs(ave(go$pvalue, go$ModuleID, go$Ontology, FUN = function(x) stats::p.adjust(x, "BH")) - go$p.adjust)) < 1e-12)   # q = BH within module and ontology
  ft <- as.data.frame(s$wgcna_feature_table); stopifnot("wgcna_exclusion_reason" %in% names(ft))
  grid <- read_csv(file.path(dirname(dirname(STATE[[v]](ds))), "tables", "supermodules", "supermodule_clustering_sensitivity.csv"), show_col_types = FALSE) |>
    distinct(cut_height, n_supermodules) |> arrange(cut_height)
  used <- abs(grid$cut_height - p$supermodule_merge_cut_height) < 1e-9; n_sm <- sum(rsm$version == v & rsm$dataset == ds)
  if (any(used)) stopifnot(sum(used) == 1, grid$n_supermodules[used] == n_sm) else
    grid <- bind_rows(grid, tibble(cut_height = p$supermodule_merge_cut_height, n_supermodules = n_sm)) |> arrange(cut_height)   # the grid lacks the height used
  bg <- go |> group_by(Ontology) |> summarise(n = max(as.integer(sub("^.*/", "", BgRatio))), .groups = "drop")
  # design: animal and group of every sample entering the network
  si <- as.data.frame(s$sample_info); ii <- match(rownames(s$expression.data), rownames(si)); stopifnot(!anyNA(ii))
  grp <- toupper(as.character(si$ExpGroup[ii])); animal <- sub("^.*_(A[0-9]+)_.*$", "\\1", rownames(s$expression.data))
  stopifnot(all(animal %in% ANIMALS), all(grp %in% c("CON", "RES", "SUS")), !anyDuplicated(distinct(tibble(animal, grp))$animal))
  ag <- distinct(tibble(animal, grp))
  st <- stability_per_animal(ds, v, long)
  sym <- sym_of(long$EntrezID)
  long <- long |> mutate(entrez = as.character(EntrezID), symbol = coalesce(unname(sym[entrez]), na_if(as.character(GeneSymbol), "")))
  # hubs as the labeller takes them: the 10 highest-|kME| proteins with an Entrez ID, one per Entrez ID
  hubs <- long |> filter(is_module(ModuleID), !is.na(entrez)) |> group_by(ModuleID) |> arrange(desc(abs_kME), .by_group = TRUE) |>
    distinct(entrez, .keep_all = TRUE) |> slice_head(n = rules$hub_n) |> ungroup()
  hubs_all[[length(hubs_all) + 1L]] <- hubs |> transmute(version = v, dataset = ds, ModuleID, ProteinGroupID, entrez, kME = as.numeric(kME),
    hub_name = coalesce(symbol, as.character(RepresentativeUniProt)), labeller_name = coalesce(as.character(GeneSymbol), ""))
  nets[[length(nets) + 1L]] <- tibble(version = v, dataset = ds, samples = nrow(s$expression.data), proteins = ncol(s$expression.data),
    groups = sprintf("CON %d, RES %d, SUS %d animals; %d, %d, %d samples", sum(ag$grp == "CON"), sum(ag$grp == "RES"), sum(ag$grp == "SUS"),
                     sum(grp == "CON"), sum(grp == "RES"), sum(grp == "SUS")), n_animals = nrow(ag),
    n_con = sum(ag$grp == "CON"), n_res = sum(ag$grp == "RES"), n_sus = sum(ag$grp == "SUS"),
    gene_mapped = n_distinct(long$entrez[!is.na(long$entrez)]), modules = n_distinct(long$ModuleID[is_module(long$ModuleID)]),
    unassigned = sum(!is_module(long$ModuleID)), supermodules = sum(rsm$version == v & rsm$dataset == ds),
    correlation = sprintf("%s (maxPOutliers %.2f)", p$correlation_function, p$bicor_maxPOutliers),
    network = p$network_type, rsq = p$soft_threshold_rsquared, power = s$softPower, min_size = p$min_module_size, deep_split = p$deep_split,
    merge = p$module_merge_cut_height, sm_cut = p$supermodule_merge_cut_height, sm_rule = p$supermodule_merge_rule,
    go_min = p$module_go_min_gs_size, go_max = p$module_go_max_gs_size, annotation = p$gene_annotation_contract_version,
    bg_bp = bg$n[bg$Ontology == "BP"], bg_cc = bg$n[bg$Ontology == "CC"], bg_mf = bg$n[bg$Ontology == "MF"], stab_ari = st$ari,
    na_values = sum(is.na(s$expression.data)), n_contam = sum(grepl("contaminant", ft$wgcna_exclusion_reason)),
    sm_grid = paste(sprintf("%.2f%s: %d", grid$cut_height, ifelse(abs(grid$cut_height - p$supermodule_merge_cut_height) < 1e-9, " (used)", ""), grid$n_supermodules), collapse = "; "))
  symmap <- setNames(long$symbol, long$entrez)
  go_raw[[length(go_raw) + 1L]] <- go |> transmute(version = v, dataset = ds, ModuleID, Ontology, ID, Description, p.adjust, q_net, Count, GeneRatio, BgRatio,
    geneID = as.character(geneID))
  core_all[[length(core_all) + 1L]] <- g |> filter(ModuleProteinSetType == "core_kME_0.6") |>
    transmute(version = v, dataset = ds, ModuleID, ID, core_q = p.adjust, core_n = Count)
  prot_all[[length(prot_all) + 1L]] <- long |> transmute(version = v, dataset = ds, ModuleID = ifelse(is_module(ModuleID), ModuleID, "unassigned"), ProteinGroupID,
    protein = coalesce(na_if(as.character(original_identifier), ""), na_if(as.character(RepresentativeUniProt), "")), uniprot = as.character(RepresentativeUniProt),
    gene = symbol, entrez, kME = as.numeric(kME), core = as.logical(is_core_kME_0.6))
  stab_all[[length(stab_all) + 1L]] <- st$tab |> mutate(version = v, dataset = ds)
  go_raw[[length(go_raw)]]$genes <- vapply(strsplit(go_raw[[length(go_raw)]]$geneID, "/", fixed = TRUE),
    function(e) paste(coalesce(unname(symmap[e]), unname(sym[e]), e), collapse = ", "), "")
  cat(v, ds, ": modules", nets[[length(nets)]]$modules, "| GO terms tested", nrow(go), "| stability ARI", round(st$ari, 3), "\n")
}
nets <- bind_rows(nets); go_raw <- bind_rows(go_raw); core_all <- bind_rows(core_all); prot_all <- bind_rows(prot_all)
stab_all <- bind_rows(stab_all); hubs_all <- bind_rows(hubs_all)
go_all <- go_raw |> filter(p.adjust < rules$q)
stopifnot(all(nets$unassigned == 0), all(nets$na_values == 0), all(hubs_all$kME > 0), n_distinct(nets$go_min) == 1, n_distinct(nets$go_max) == 1)
for (ds in names(DATASETS)) stopifnot(n_distinct(nets$sm_cut[nets$dataset == ds]) == 1)   # the same supermodule cut in both analyses
stab_sum <- stab_all |> group_by(version, dataset, ModuleID) |>
  summarise(recovered = sum(jaccard >= rules$stable_jaccard, na.rm = TRUE), rebuilds = sum(!is.na(jaccard)), med = median(jaccard, na.rm = TRUE),
            min = min(jaccard, na.rm = TRUE), .groups = "drop")
chk_stab <- rmod |> select(version, dataset, ModuleID, stability_n_recovered, stability_median_jaccard) |> inner_join(stab_sum, by = c("version", "dataset", "ModuleID"))
stopifnot(nrow(chk_stab) == nrow(rmod), all(chk_stab$stability_n_recovered == chk_stab$recovered), all(abs(chk_stab$stability_median_jaccard - chk_stab$med) < 1e-9))
hub_str <- hubs_all |> group_by(version, dataset, ModuleID) |> summarise(hubs = paste(hub_name, collapse = ", "), labeller = paste(labeller_name, collapse = ", "), .groups = "drop")
chk_hub <- rmod |> select(version, dataset, ModuleID, hubs) |> inner_join(hub_str, by = c("version", "dataset", "ModuleID"))
if (!all(toupper(chk_hub$hubs.x) == toupper(chk_hub$labeller)))   # same hubs as the labeller used for hub support
  stop("Hubs differ from module_rule_classes.csv: the WGCNA states are newer than the labeller output. Rerun label_modules_by_rule.R, ",
       "derive_supermodule_labels.R and check_rule_labels.R first.", call. = FALSE)
K <- c("version", "dataset", "ModuleID")

# ----------------------------------------------------------------------------------- named GO terms of every module label
anc_of <- function(id, ont) {
  a <- switch(ont, BP = GO.db::GOBPANCESTOR, CC = GO.db::GOCCANCESTOR, MF = GO.db::GOMFANCESTOR)
  tryCatch(setdiff(AnnotationDbi::get(id, a), "all"), error = function(e) character())
}
id_in <- go_raw |> distinct(version, dataset, ModuleID, Description, ID)
sig_info <- bind_rows(rsig, rsig_all) |> transmute(version, dataset, ModuleID, grouping = ontology_set, signal, leading_term, best_term, n_terms, compartment)
lt <- lt |> left_join(go_raw |> select(all_of(K), term_id = ID, Ontology, q = p.adjust, q_net, n = Count, geneID), by = c(K, "term_id")) |>
  left_join(core_all |> rename(term_id = ID), by = c(K, "term_id")) |> left_join(sig_info, by = c(K, "grouping", "signal")) |>
  left_join(id_in |> rename(leading_term = Description, lead_id = ID), by = c(K, "leading_term")) |>
  left_join(id_in |> rename(best_term = Description, best_id = ID), by = c(K, "best_term"))
stopifnot(all(lt$q < rules$q), !anyNA(lt$lead_id), !anyNA(lt$best_id))   # every named term is significant in its module
NET_KEEP <- sum(lt$q_net < rules$q)   # named terms still significant with BH across all modules and ontologies of their network
role_of <- function(term_id, lead_id, best_id, anc, leading_term, best_term) {   # how a named term relates to its signal's leading and largest terms
  la <- lead_id %in% anc; ba <- best_id %in% anc; same <- lead_id == best_id
  if (term_id == lead_id && term_id == best_id) "the leading and largest term of its signal"
  else if (term_id == lead_id) sprintf("the leading term of its signal (largest term: %s)", best_term)
  else if (term_id == best_id) sprintf("the largest term of its signal (leading term: %s)", leading_term)
  else if (same && la) sprintf("more specific than its signal's leading and largest term, %s (a GO ancestor)", leading_term)
  else if (la && ba) sprintf("more specific than its signal's leading term, %s, and largest term, %s (both GO ancestors)", leading_term, best_term)
  else if (ba) sprintf("more specific than its signal's largest term, %s (a GO ancestor); leading term: %s", best_term, leading_term)
  else if (la) sprintf("more specific than its signal's leading term, %s (a GO ancestor); largest term: %s", leading_term, best_term)
  else if (same) sprintf("a further term of its signal (leading and largest term: %s)", leading_term)
  else sprintf("a further term of its signal (leading term: %s; largest term: %s)", leading_term, best_term)
}
lt$anc <- mapply(anc_of, lt$term_id, lt$Ontology, SIMPLIFY = FALSE); lt$depth <- lengths(lt$anc)
lt$role <- unname(mapply(role_of, lt$term_id, lt$lead_id, lt$best_id, lt$anc, lt$leading_term, lt$best_term))
lt <- lt |> mutate(core_txt = sprintf("%s: %s", term, ifelse(is.na(core_q), "no core member carries it", ifelse(core_q < rules$q, sprintf("q = %s (%d proteins)", fq(core_q), as.integer(core_n)),
                                                                                    sprintf("not significant (q = %s)", fq(core_q))))),
         named_txt = sprintf("%s (%s; q = %s; %d proteins)", term, term_id, fq(q), as.integer(n)),
         sig_word = ifelse(signal_class == "unannotated (weak)", "the sub-threshold signal", ifelse(named_signal == 1, "the dominant signal", sprintf("signal %d", signal))),
         wording = sprintf("'%s' = %s (%s): %s", part, term, sig_word, role))
named <- lt |> group_by(version, dataset, ModuleID) |>
  summarise(named = paste(named_txt, collapse = " | "), core_named = paste(core_txt, collapse = " | "), wording = paste(wording, collapse = " | "), .groups = "drop")

# ----------------------------------------------------------------------------------- correspondence between the analyses and rule 8
pset <- prot_all |> filter(ModuleID != "unassigned") |> left_join(sm_of, by = K)
pair_tab <- function(key) {   # every pair of entities of the two analyses that share proteins, per compartment
  a <- pset |> filter(version == "original") |> transmute(dataset, ProteinGroupID, p = .data[[key]]); b <- pset |> filter(version == "new") |> transmute(dataset, ProteinGroupID, s = .data[[key]])
  shared_ids <- inner_join(a |> distinct(dataset, ProteinGroupID), b |> distinct(dataset, ProteinGroupID), by = c("dataset", "ProteinGroupID"))
  a <- a |> semi_join(shared_ids, by = c("dataset", "ProteinGroupID")); b <- b |> semi_join(shared_ids, by = c("dataset", "ProteinGroupID"))
  inner_join(a, b, by = c("dataset", "ProteinGroupID")) |> count(dataset, p, s, name = "shared") |>
    left_join(a |> count(dataset, p, name = "n_p"), by = c("dataset", "p")) |> left_join(b |> count(dataset, s, name = "n_s"), by = c("dataset", "s")) |>
    mutate(share_p = shared / n_p, share_s = shared / n_s, jaccard = shared / (n_p + n_s - shared))
}
mpairs <- pair_tab("ModuleID"); spairs <- pair_tab("SupermoduleID")
chk_lin <- rmod |> filter(version == "new", !is.na(lineage_module)) |> select(dataset, s = ModuleID, p = lineage_module, lineage_share) |>
  left_join(mpairs, by = c("dataset", "p", "s"))
if (any(abs(chk_lin$share_s - chk_lin$lineage_share) > 0.005, na.rm = TRUE) || anyNA(chk_lin$share_s))
  stop("Module shares between the analyses differ from the labeller's lineage table; rerun label_modules_by_rule.R.", call. = FALSE)
best_match <- function(pairs, lab_p, lab_s) bind_rows(
  pairs |> group_by(dataset, p) |> slice_max(jaccard, n = 1, with_ties = FALSE) |> ungroup() |> left_join(lab_s, by = c("dataset", "s")) |>
    transmute(version = "original", dataset, id = p, best = ifelse(jaccard < 0.1, sprintf("none with Jaccard >= 0.1 (highest %.2f)", jaccard), sprintf("sensitivity %s (Jaccard %.2f): %s", short(s), jaccard, l))),
  pairs |> group_by(dataset, s) |> slice_max(jaccard, n = 1, with_ties = FALSE) |> ungroup() |> left_join(lab_p, by = c("dataset", "p")) |>
    transmute(version = "new", dataset, id = s, best = ifelse(jaccard < 0.1, sprintf("none with Jaccard >= 0.1 (highest %.2f)", jaccard), sprintf("primary %s (Jaccard %.2f): %s", short(p), jaccard, l))))
bm_mod <- best_match(mpairs, mlab |> filter(version == "original") |> transmute(dataset, p = ModuleID, l = label), mlab |> filter(version == "new") |> transmute(dataset, s = ModuleID, l = label))
bm_sm <- best_match(spairs, slab |> filter(version == "original") |> transmute(dataset, p = SupermoduleID, l = label), slab |> filter(version == "new") |> transmute(dataset, s = SupermoduleID, l = label))
# rule 8: a carried module uses its primary module's words for the shared signal, when they name terms of its own signals
own_sig_ids <- rterm |> semi_join(rsig |> filter(comparable), by = c(K, "ontology_set", "signal")) |> distinct(version, dataset, ModuleID, term_id)
ids_of <- function(x) if (is.na(x) || !nzchar(x)) character() else strsplit(x, ";", fixed = TRUE)[[1]]
prim_info <- rmod |> filter(version == "original") |> transmute(dataset, lineage_module = ModuleID, p_class = signal_class, p_lead = dominant_leading_id, p_ids = dominant_term_ids)
r8 <- rmod |> filter(version == "new") |> select(version, dataset, ModuleID, signal_class, lineage_module, lineage_share, lineage_class, comparable_term_ids) |>
  left_join(prim_info, by = c("dataset", "lineage_module")) |> rowwise() |> mutate(
  j = if (is.na(p_ids)) NA_real_ else jac(ids_of(comparable_term_ids), ids_of(p_ids)),
  lead_in = !is.na(p_lead) && nzchar(p_lead) && p_lead %in% ids_of(comparable_term_ids),
  lead_name = if (!is.na(p_lead) && nzchar(p_lead)) unname(AnnotationDbi::Term(p_lead)) else "",
  own = list(lt$part[lt$version == "new" & lt$dataset == dataset & lt$ModuleID == ModuleID]),
  prim = list(lt$part[lt$version == "original" & lt$dataset == dataset & lt$ModuleID %in% lineage_module]),
  prim_ids = list(lt$term_id[lt$version == "original" & lt$dataset == dataset & lt$ModuleID %in% lineage_module]),
  shared = list(own[tolower(own) %in% tolower(prim)]),
  prim_in_own = any(prim_ids %in% own_sig_ids$term_id[own_sig_ids$version == "new" & own_sig_ids$dataset == dataset & own_sig_ids$ModuleID == ModuleID]),
  continues = if (!is.na(lineage_share) && lineage_share >= rules$carry_share) sprintf("primary %s (%.0f%% of its proteins)", short(lineage_module), 100 * lineage_share) else "",
  rule8 = case_when(
    signal_class == "unannotated (weak)" ~ "no: no passing signal (unannotated (weak))",
    grepl("^unannotated", signal_class) ~ "no: not labelled",
    lineage_class %in% "carried" & length(shared) > 0 ~ sprintf("yes: %s", paste(shared, collapse = ", ")),
    lineage_class %in% "carried" & !prim_in_own ~ sprintf("no: the terms named by primary %s are not terms of this module's signals", short(lineage_module)),
    lineage_class %in% "carried" ~ "VIOLATION",
    lineage_class %in% "revised" & grepl("^unannotated", p_class) ~ sprintf("no: primary %s is unannotated", short(lineage_module)),
    lineage_class %in% "revised" & !lead_in & j < rules$term_jaccard ~ sprintf("no: the leading term of primary %s (%s) is not among the terms of this module's comparable signals, and their term sets overlap by Jaccard %.2f (below %.1f)",
                                                                                   short(lineage_module), lead_name, j, rules$term_jaccard),
    lineage_class %in% "revised" ~ "VIOLATION",
    TRUE ~ "no: no primary module holds half of its proteins")) |> ungroup()
if (any(r8$rule8 == "VIOLATION")) stop("Step 8 not followed or not explained for sensitivity modules: ", paste(r8$dataset[r8$rule8 == "VIOLATION"], r8$ModuleID[r8$rule8 == "VIOLATION"], collapse = ", "), call. = FALSE)

# ----------------------------------------------------------------------------------- reader notes (templates filled and checked from the data)
term_genes <- function(v, ds, m, id) { x <- go_raw |> filter(version == v, dataset == ds, ModuleID == m, ID == id); if (!nrow(x)) character() else strsplit(x$genes, ", ", fixed = TRUE)[[1]] }
need <- function(genes, have, what) { miss <- setdiff(genes, have); if (length(miss)) stop(what, " no longer holds ", paste(miss, collapse = ", "), call. = FALSE); paste(genes, collapse = ", ") }
mod_genes <- function(v, ds, m) prot_all$gene[prot_all$version == v & prot_all$dataset == ds & prot_all$ModuleID == m]
notes <- list()
add_note <- function(v, ds, m, txt) notes[[length(notes) + 1L]] <<- tibble(version = v, dataset = ds, ModuleID = m, note = txt)
# contamination: a significant cornified envelope term with proteins specific to the epidermis
EPIDERMAL <- c("Flg", "Flg2", "Sprr1a", "Sprr1b", "Tgm1", "Tgm3", "Lor", "Ivl", "Pkp1", "Krt1", "Krt10", "Krt14", "Krt5", "Casp14", "Cdsn", "Dsc1", "Hrnr")
ce <- go_all |> filter(ID == "GO:0001533") |> left_join(mlab, by = K)
for (i in seq_len(nrow(ce))) {
  ce_genes <- strsplit(ce$genes[i], ", ", fixed = TRUE)[[1]]; epi <- intersect(ce_genes, EPIDERMAL); if (!length(epi)) next
  pm <- prot_all |> filter(version == ce$version[i], dataset == ce$dataset[i], ModuleID == ce$ModuleID[i])
  k <- pm |> filter(gene %in% ce_genes); top <- pm |> filter(!is.na(gene)) |> slice_max(kME, n = 5, with_ties = FALSE)
  add_note(ce$version[i], ce$dataset[i], ce$ModuleID[i], if (grepl("cornified", ce$label[i])) sprintf(
    "Named after cornified envelope (GO:0001533; %d proteins, q = %s), whose proteins include the epidermal proteins %s, likely skin or handling contamination; the term is not interpreted as biology. %s (kME %.2f to %.2f); the gene-mapped members with the highest kME are %s.",
    as.integer(ce$Count[i]), fq(ce$p.adjust[i]), paste(epi, collapse = ", "),
    if (any(k$core %in% TRUE)) sprintf("%d of these %d proteins are core members", sum(k$core %in% TRUE), nrow(k)) else sprintf("None of these %d proteins is a core member", nrow(k)),
    min(k$kME), max(k$kME), paste(top$gene, collapse = ", ")) else sprintf(
    "%d of its %s proteins (%s) are epidermal proteins of the cornified envelope term (GO:0001533, q = %s), likely skin or handling contamination; they do not affect the label.",
    length(epi), format(nrow(pm), big.mark = ","), paste(epi, collapse = ", "), fq(ce$p.adjust[i])))
}
local({   # sensitivity microglia m15 takes up the contamination proteins of primary microglia m09
  x <- mpairs |> filter(dataset == "microglia", p == "WGCNA_m09", s == "WGCNA_m15"); top <- prot_all |> filter(version == "new", dataset == "microglia", ModuleID == "WGCNA_m15") |> slice_max(kME, n = 1, with_ties = FALSE)
  g <- need(c("Prss3b", "Try10", "Sprr1b", "Flg2"), mod_genes("new", "microglia", "WGCNA_m15"), "Sensitivity microglia m15")
  stopifnot(nrow(x) == 1, top$gene == "Prss3b")
  add_note("new", "microglia", "WGCNA_m15", sprintf("Holds %d of the %d proteins of primary microglia m09, among them the trypsins Prss3b (the member of m15 with the highest kME) and Try10, which may derive from the digestion enzyme, and the epidermal proteins Sprr1b and Flg2, common handling contaminants; the module may be technical. The weak label names its only sub-threshold signal.",
                                                    x$shared, x$n_p))
})
local({   # primary microglia m04: the label rests on its only passing signal
  f <- rsig |> filter(version == "original", dataset == "microglia", ModuleID == "WGCNA_m04", !passing); x <- f |> slice_min(leading_q, n = 1, with_ties = FALSE)
  g <- need(c("Actb", "Cdc42", "Rhoa"), term_genes("original", "microglia", "WGCNA_m04", "GO:0022402"), "Primary microglia m04 'cell cycle process'")
  stopifnot(nrow(x) == 1, sum(rsig$passing[rsig$version == "original" & rsig$dataset == "microglia" & rsig$ModuleID == "WGCNA_m04"]) == 1)
  add_note("original", "microglia", "WGCNA_m04", sprintf("Labelled by its only passing signal. %s; the more significant is led by %s (q = %s; %d proteins): %s. 'Cell cycle process' rests on general cytoskeletal and signalling proteins (e.g. %s) and does not indicate proliferation.",
                                                         if (nrow(f) == 1) "One other signal does not pass the threshold" else sprintf("%d other signals do not pass the threshold", nrow(f)),
                                                         x$leading_term, fq(x$leading_q), as.integer(x$leading_count), x$fails_because, g))
})
local({   # primary neuropil m04: named after synaptic vesicle cycle, not its vague leading term
  a <- term_genes("original", "neuron_neuropil", "WGCNA_m04", "GO:0070050"); b <- term_genes("original", "neuron_neuropil", "WGCNA_m04", "GO:0099504")
  ab <- intersect(a, b); stopifnot(length(ab) > length(a) / 2)
  add_note("original", "neuron_neuropil", "WGCNA_m04", sprintf("Named after synaptic vesicle cycle (%d proteins) rather than its signal's leading term, neuron cellular homeostasis (%d proteins): %d of the latter's proteins also carry synaptic vesicle cycle, %d of them V-ATPase subunits.",
                                                               length(b), length(a), length(ab), sum(grepl("^Atp6", ab))))
})
# 'ER stress response' is a GO term, not the social stress
for (i in which(grepl("ER stress response", mlab$label, fixed = TRUE))) add_note(mlab$version[i], mlab$dataset[i], mlab$ModuleID[i],
  "'ER stress response' is the GO process response to endoplasmic reticulum stress (GO:0034976); it does not refer to the social stress of the experiment.")
# unannotated modules with significant terms: why they carry no label
un <- rmod |> filter(signal_class == "unannotated") |> inner_join(rsig_all, by = K) |> group_by(version, dataset, ModuleID) |>
  summarise(groups = n(), lq = min(leading_q), top = list(pick(everything())[abs(leading_q - min(leading_q)) < 1e-12, ]), .groups = "drop")
for (m in setdiff(paste(rmod$version, rmod$dataset, rmod$ModuleID)[rmod$signal_class == "unannotated"], paste(un$version, un$dataset, un$ModuleID))) {
  k <- strsplit(m, " ", fixed = TRUE)[[1]]; add_note(k[1], k[2], k[3], "Not labelled: no GO term is significant in this module.")
}
for (i in seq_len(nrow(un))) {
  t <- un$top[[i]]; leads <- paste(sprintf("%s (%s; %d proteins)", t$leading_term, t$leading_ontology, as.integer(t$leading_count)), collapse = " and ")
  add_note(un$version[i], un$dataset[i], un$ModuleID[i], sprintf("Not labelled: its significant terms form %d separate sub-threshold signals. %s: %s.", un$groups[i],
    if (nrow(t) == 1) sprintf("The most significant is led by %s, q = %s, and does not pass the threshold", leads, fq(un$lq[i]))
    else sprintf("The most significant, tied at q = %s, are led by %s and do not pass the threshold", fq(un$lq[i]), leads),
    paste(unique(t$fails_because), collapse = "; ")))
}
# members of a concordant supermodule share their dominant signal
dom_ids <- rterm |> inner_join(rsig |> filter(signal == 1, passing) |> select(all_of(K), ontology_set), by = c(K, "ontology_set")) |> filter(signal == 1)
conc <- rsm |> filter(rule_class == "concordant") |> separate_rows(member_modules, sep = ";")
for (k in unique(paste(conc$version, conc$dataset, conc$SupermoduleID))) {
  x <- conc[paste(conc$version, conc$dataset, conc$SupermoduleID) == k, ]
  for (m in x$member_modules) for (o in setdiff(x$member_modules, m)) {
    a <- dom_ids$term_id[dom_ids$version == x$version[1] & dom_ids$dataset == x$dataset[1] & dom_ids$ModuleID == m]
    b <- dom_ids$term_id[dom_ids$version == x$version[1] & dom_ids$dataset == x$dataset[1] & dom_ids$ModuleID == o]
    add_note(x$version[1], x$dataset[1], m, sprintf("Its dominant signal is shared with %s (term sets: Jaccard %.2f); together they form the concordant supermodule %s.",
                                                    short(o), jac(a, b), x$SupermoduleID[1]))
  }
}
# signals that hold a single, very general GO term
gen <- lt |> filter(named_signal == 1, n_terms == 1, depth <= 3)
for (i in seq_len(nrow(gen))) add_note(gen$version[i], gen$dataset[i], gen$ModuleID[i], sprintf(
  "The signal holds a single, very general GO term (%s, %s); the label names it because the signal holds no other term, and says little beyond it.", gen$term[i], gen$term_id[i]))
notes <- bind_rows(notes) |> group_by(version, dataset, ModuleID) |> summarise(note = paste(note, collapse = " "), .groups = "drop")

# ----------------------------------------------------------------------------------- tables
pct <- function(x) ifelse(is.na(x), NA_real_, 100 * x)
signal_of <- rterm |> group_by(version, dataset, ModuleID, ontology_set, term_id) |> summarise(signal = min(signal), .groups = "drop")
lead_ev <- rsig |> group_by(version, dataset, ModuleID) |> filter(passing) |> slice_head(n = 1) |> ungroup() |>
  transmute(version, dataset, ModuleID, lead_txt = sprintf("%s (%s; q = %s; %d proteins)", leading_term, leading_ontology, fq(leading_q), as.integer(leading_count)),
            best_txt = sprintf("%s (%d proteins)", best_term, as.integer(best_count)))
n_comp <- rsig |> group_by(version, dataset, ModuleID) |> summarise(n_comparable = sum(comparable), .groups = "drop")
n_core <- prot_all |> filter(ModuleID != "unassigned") |> group_by(version, dataset, ModuleID) |> summarise(n_core = sum(core %in% TRUE), .groups = "drop")
mod_base <- rmod |> left_join(mlab, by = K) |> left_join(sm_of, by = K) |> left_join(lead_ev, by = K) |> left_join(stab_sum, by = K) |>
  left_join(n_comp, by = K) |> left_join(n_core, by = K) |> left_join(hub_str |> select(all_of(K), hub_names = hubs), by = K) |> left_join(named, by = K) |>
  left_join(notes, by = K) |> left_join(r8 |> select(all_of(K), continues, rule8), by = K) |> left_join(bm_mod |> rename(ModuleID = id), by = K) |> ord()
unann <- function(cls) grepl("^unannotated", cls)
modules <- mod_base |> transmute(Analysis = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), Supermodule = coalesce(SupermoduleID, ""),
    Proteins = n_proteins, `Gene-mapped proteins` = n_gene_mapped, `Core members (kME >= 0.6)` = n_core, Label = label, `Signal class` = signal_class,
    `Annotation confidence` = rule_confidence, `Named GO terms` = coalesce(named, ""), `How the words were chosen` = coalesce(wording, ""),
    `Comparable signals (n)` = ifelse(unann(signal_class), NA_integer_, coalesce(n_comparable, 0L)),
    `Dominant signal: leading term` = ifelse(unann(signal_class), "", coalesce(lead_txt, "")), `Dominant signal: largest term` = ifelse(unann(signal_class), "", coalesce(best_txt, "")),
    `Dominant signal: top terms` = coalesce(dominant_signal, ""), `Second signal: top terms` = coalesce(second_signal, ""), `Third signal: top terms` = coalesce(third_signal, ""),
    `Weak association` = ifelse(nzchar(coalesce(weak_association, "")), sprintf("%s (%s; largest term %d proteins)", weak_association, weak_ontologies, as.integer(weak_size)), ""),
    `Signals grouped from` = case_when(unann(signal_class) ~ "", signal_basis == "BP" ~ "BP terms", TRUE ~ "BP, CC and MF terms (no passing BP signal)"),
    `Ontologies with significant terms` = ifelse(nzchar(coalesce(module_ontologies, "")), module_ontologies, "none"),
    `Coverage (%)` = pct(coverage), `Hub support (%)` = pct(hub_support), `Hubs: top 10 gene-mapped by kME` = coalesce(hub_names, ""),
    `Named terms in core members (kME >= 0.6)` = coalesce(core_named, ""),
    `Stability: recovered in (of 9)` = recovered, `Stability: median Jaccard` = med, `Stability: lowest Jaccard` = min,
    `Continues primary module` = coalesce(continues, ""), `Wording from primary module (step 8)` = coalesce(rule8, ""),
    `Most similar module in the other analysis (Jaccard)` = coalesce(best, ""), `Note for readers` = coalesce(note, ""))
sm_named <- lt |> inner_join(sm_of, by = K) |> left_join(slab |> rename(sm_label = label), by = c("version", "dataset", "SupermoduleID")) |>
  filter(mapply(function(p, l) grepl(tolower(p), tolower(l), fixed = TRUE), part, sm_label)) |>
  group_by(version, dataset, SupermoduleID) |> summarise(named = paste(sprintf("%s: %s", short(ModuleID), named_txt), collapse = " | "), .groups = "drop")
sm_members <- rsm |> separate_rows(member_modules, sep = ";") |> left_join(mlab, by = c("version", "dataset", "member_modules" = "ModuleID")) |>
  left_join(stab_sum |> select(version, dataset, member_modules = ModuleID, recovered, med), by = c("version", "dataset", "member_modules")) |>
  left_join(rmod |> select(version, dataset, member_modules = ModuleID, n_proteins), by = c("version", "dataset", "member_modules")) |>
  group_by(version, dataset, SupermoduleID) |>
  summarise(member_labels = paste(sprintf("%s: %s", short(member_modules), label), collapse = " || "), proteins = sum(n_proteins),
            member_stab = paste(sprintf("%s %d of 9", short(member_modules), as.integer(recovered)), collapse = "; "),
            low_rec = min(recovered), low_med = min(med), .groups = "drop")
sm_base <- rsm |> left_join(slab, by = c("version", "dataset", "SupermoduleID")) |> left_join(sm_members, by = c("version", "dataset", "SupermoduleID")) |>
  left_join(sm_named, by = c("version", "dataset", "SupermoduleID")) |> left_join(bm_sm |> rename(SupermoduleID = id), by = c("version", "dataset", "SupermoduleID")) |>
  left_join(nets |> select(version, dataset, sm_cut), by = c("version", "dataset")) |> ord()
supermodules <- sm_base |> transmute(Analysis = lab_c(version), Compartment = lab_ds(dataset), Supermodule = SupermoduleID,
  `Member modules` = gsub(";", ", ", gsub("WGCNA_", "", member_modules)), Proteins = proteins, Label = label, Class = rule_class, `Annotation confidence` = rule_confidence,
  `Named GO terms` = coalesce(named, ""), `Members and their labels` = member_labels, `Members' stability (recovered in, of 9)` = member_stab,
  `Formed by` = sprintf("average-linkage clustering of module eigengenes on 1 - Pearson correlation, cut at %.2f", sm_cut),
  `Most similar supermodule in the other analysis (Jaccard)` = coalesce(best, ""))
labels_sheet <- bind_rows(
  mod_base |> transmute(o = 1, version, dataset, Level = "module", ID = short(ModuleID), `Supermodule or member modules` = coalesce(SupermoduleID, ""), Proteins = n_proteins,
    Label = label, Class = signal_class, `Annotation confidence` = rule_confidence, `Named GO terms` = coalesce(named, ""),
    `Dominant signal (leading term; largest term)` = ifelse(unann(signal_class), "", sprintf("%s; %s", lead_txt, best_txt)),
    `Coverage (%)` = pct(coverage), `Hub support (%)` = pct(hub_support), `Named terms in core members (kME >= 0.6)` = coalesce(core_named, ""),
    `Stability: recovered in (of 9)` = recovered, `Stability: median Jaccard` = med, `Most similar in the other analysis (Jaccard)` = coalesce(best, ""),
    `Continues primary module` = coalesce(continues, ""), `Wording from primary module (step 8)` = coalesce(rule8, ""), `Note for readers` = coalesce(note, "")),
  sm_base |> transmute(o = 2, version, dataset, Level = "supermodule", ID = SupermoduleID, `Supermodule or member modules` = gsub(";", ", ", gsub("WGCNA_", "", member_modules)),
    Proteins = proteins, Label = label, Class = rule_class, `Annotation confidence` = rule_confidence, `Named GO terms` = coalesce(named, ""),
    `Dominant signal (leading term; largest term)` = "", `Coverage (%)` = NA_real_, `Hub support (%)` = NA_real_, `Named terms in core members (kME >= 0.6)` = "",
    `Stability: recovered in (of 9)` = low_rec, `Stability: median Jaccard` = low_med, `Most similar in the other analysis (Jaccard)` = coalesce(best, ""),
    `Continues primary module` = "", `Wording from primary module (step 8)` = "", `Note for readers` = "")) |>
  arrange(factor(version, names(CENT)), factor(dataset, names(DATASETS)), o, ID) |>
  mutate(Analysis = lab_c(version), Compartment = lab_ds(dataset), .before = 1) |> select(-o, -version, -dataset) |> relocate(Label, .after = ID)
stopifnot(nrow(labels_sheet) == nrow(lab), !anyDuplicated(paste(labels_sheet$Analysis, labels_sheet$Compartment, labels_sheet$Level, labels_sheet$ID)))
cnt_tab <- bind_rows(
  rmod |> transmute(version, dataset, what = paste("Modules:", signal_class)), rmod |> transmute(version, dataset, what = paste("Modules, annotation confidence:", rule_confidence)),
  rmod |> transmute(version, dataset, what = "Modules (all)"), rsm |> transmute(version, dataset, what = "Supermodules (all)"),
