stopifnot(all(cnt_tab$what %in% LEVELS))
COLS <- as.vector(outer(lab_ds(names(DATASETS)), WORD, function(d, w) paste(w, d, sep = ": ")))
counts <- cnt_tab |> select(what, col, n) |> pivot_wider(names_from = col, values_from = n, values_fill = 0) |>
  right_join(tibble(what = LEVELS), by = "what") |> mutate(what = factor(what, LEVELS)) |> arrange(what) |> mutate(what = as.character(what))
for (cc in COLS) if (!cc %in% names(counts)) counts[[cc]] <- 0L
counts <- counts |> mutate(across(all_of(COLS), ~ as.integer(coalesce(.x, 0L)))) |> select(Count = what, all_of(COLS))
