stopifnot(sum(counts[counts$Count == "Modules (all)", -1]) == nrow(rmod), sum(counts[counts$Count == "Supermodules (all)", -1]) == nrow(rsm))
sig_tab <- function(x) x |> ord() |> transmute(Analysis = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), Grouping = grouping, Signal = signal,
