            `q (BH)` = p.adjust, `Module proteins with term` = Count, `Module proteins annotated in this ontology` = as.integer(sub("^.*/", "", GeneRatio)),
            `Background proteins with term` = as.integer(sub("/.*$", "", BgRatio)), `Background proteins annotated in this ontology` = as.integer(sub("^.*/", "", BgRatio)),
            `Fold enrichment` = (Count / as.integer(sub("^.*/", "", GeneRatio))) / (as.integer(sub("/.*$", "", BgRatio)) / as.integer(sub("^.*/", "", BgRatio))),
            `In signal (classifying grouping)` = sig_cls, `In signal (weak/unannotated grouping)` = sig_all, `Named in the label` = coalesce(named, ""), `Proteins (gene symbols)` = genes)
stopifnot(sum(go_tab$`Named in the label` == "yes") == nrow(distinct(lt, version, dataset, ModuleID, term_id)))
hub_flag <- hubs_all |> transmute(version, dataset, ProteinGroupID, is_hub = TRUE)
proteins <- prot_all |> left_join(sm_of, by = K) |> left_join(hub_flag, by = c("version", "dataset", "ProteinGroupID")) |>
  arrange(factor(version, names(CENT)), factor(dataset, names(DATASETS)), ModuleID, desc(kME)) |>
  transmute(Analysis = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), Supermodule = coalesce(SupermoduleID, ""),
            Protein = coalesce(protein, "(no UniProt entry)"), UniProt = coalesce(uniprot, ""), Gene = coalesce(gene, ""), `Entrez ID` = coalesce(entrez, ""),
            `Gene-mapped (has Entrez ID)` = ifelse(nzchar(coalesce(entrez, "")), "yes", ""), `kME (own module)` = kME,
            `Hub for hub support (top 10)` = ifelse(is_hub %in% TRUE, "yes", ""), `Core (kME >= 0.6)` = ifelse(core %in% TRUE, "yes", ""))
stability <- stab_all |> mutate(animal = factor(animal, ANIMALS)) |> arrange(animal) |>
  pivot_wider(names_from = animal, values_from = jaccard, names_prefix = "without ") |>
  left_join(stab_sum, by = K) |> arrange(factor(version, names(CENT)), factor(dataset, names(DATASETS)), ModuleID) |>
  transmute(Analysis = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), across(starts_with("without ")),
            `Recovered in (of 9)` = recovered, `Median Jaccard` = med, `Lowest Jaccard` = min)
corr <- mpairs |> filter(share_p >= 0.2 | share_s >= 0.2) |>
  left_join(mlab |> filter(version == "original") |> select(dataset, p = ModuleID, l_p = label), by = c("dataset", "p")) |>
  left_join(mlab |> filter(version == "new") |> select(dataset, s = ModuleID, l_s = label), by = c("dataset", "s")) |>
  arrange(factor(dataset, names(DATASETS)), p, desc(shared)) |>
  transmute(Compartment = lab_ds(dataset), `Primary module` = short(p), `Primary label` = l_p, `Sensitivity module` = short(s), `Sensitivity label` = l_s,
            `Shared proteins` = shared, `Share of primary module (%)` = pct(share_p), `Share of sensitivity module (%)` = pct(share_s), Jaccard = jaccard)
# Figure 3 exemplars: in each network, the module with the smallest q for the exemplar term
EXEMPLARS <- tribble(~dataset, ~term_id, ~region,
  "neuron_neuropil", "GO:0099536", "CA3 stratum radiatum (neuropil)",
  "neuron_soma", "GO:0006397", "CA2 stratum pyramidale (soma)",
  "microglia", "GO:0006119", "CA1 (microglia-enriched region)")
fig3 <- bind_rows(lapply(seq_len(nrow(EXEMPLARS)), function(i) bind_rows(lapply(names(CENT), function(v) {
  e <- EXEMPLARS[i, ]; x <- go_raw |> filter(version == v, dataset == e$dataset, ID == e$term_id) |> arrange(p.adjust, desc(Count))
  stopifnot(nrow(x) > 0, x$p.adjust[1] < rules$q)
  m <- x$ModuleID[1]; n_net <- as.integer(sub("/.*$", "", x$BgRatio[1])); n_bp <- as.integer(sub("^.*/", "", x$GeneRatio[1]))
  fold <- (x$Count[1] / n_bp) / (n_net / as.integer(sub("^.*/", "", x$BgRatio[1])))
  sig <- signal_of |> filter(version == v, dataset == e$dataset, ModuleID == m, term_id == e$term_id, !grepl("decides weak", ontology_set))
  sg <- if (nrow(sig)) rsig |> filter(version == v, dataset == e$dataset, ModuleID == m, ontology_set == sig$ontology_set[1], signal == sig$signal[1]) else NULL
  where <- if (is.null(sg)) "is significant in the module but not among the terms grouped into its signals" else
    sprintf("belongs to its %s (leading term: %s)", if (sg$signal == 1 && sg$passing) "dominant signal" else sprintf("signal %d (%s)", sg$signal, if (sg$passing) "passing" else "sub-threshold"), sg$leading_term)
  hub_n <- sum(hubs_all$entrez[hubs_all$version == v & hubs_all$dataset == e$dataset & hubs_all$ModuleID == m] %in% strsplit(x$geneID[1], "/", fixed = TRUE)[[1]])
  oth <- x[-1, ] |> filter(p.adjust < rules$q)
  nxt <- if (nrow(oth)) sprintf("; it is also over-represented (q < 0.05) in %s", paste(sprintf("%s (%d proteins, q = %s)", short(oth$ModuleID), as.integer(oth$Count), fq(oth$p.adjust)), collapse = ", ")) else
    "; no other module of the network has it at q < 0.05"
  cl <- rmod |> filter(version == v, dataset == e$dataset, ModuleID == m)
  tibble(version = v, dataset = e$dataset, Exemplar = sprintf("%s (%s)", x$Description[1], e$term_id), region = e$region, ModuleID = m,
         q = x$p.adjust[1], n_mod = as.integer(x$Count[1]), n_bp = n_bp, fold = fold, n_net = n_net, rec = stab_sum$recovered[stab_sum$version == v & stab_sum$dataset == e$dataset & stab_sum$ModuleID == m],
         note = sprintf("The module (%s proteins) holds %d of the %d network proteins annotated with the term%s. The term %s; %d of the module's 10 hubs %s it. Module class: %s, annotation confidence %s.",
                        format(cl$n_proteins, big.mark = ","), as.integer(x$Count[1]), n_net, nxt, where, hub_n, if (hub_n == 1) "carries" else "carry", cl$signal_class, cl$rule_confidence))
}))))
fig3 <- fig3 |> left_join(mlab, by = K) |> ord() |>
  transmute(Analysis = lab_c(version), Compartment = lab_ds(dataset), `Exemplar GO term` = Exemplar, `Region of the exemplar (Figure 3)` = region,
            Module = short(ModuleID), Label = label, `Exemplar term: q in module` = q, `Exemplar term: module proteins with term` = n_mod,
            `Exemplar term: BP-annotated module proteins` = n_bp, `Exemplar term: fold enrichment` = fold, `Stability: recovered in (of 9)` = rec,
            `How the module was chosen` = "the module with the smallest q for the exemplar term in this network; group and phenotype results were not used",
            `Note for readers` = note)

# ----------------------------------------------------------------------------------- facts for the text
lock <- jsonlite::fromJSON("renv.lock", simplifyVector = FALSE)
PKG <- c("WGCNA", "dynamicTreeCut", "clusterProfiler", "org.Mm.eg.db", "GO.db", "AnnotationDbi")
ver <- vapply(PKG, function(p) lock$Packages[[p]]$Version %||% NA_character_, "")
inst <- vapply(PKG, function(p) as.character(utils::packageVersion(p)), "")
if (!identical(unname(ver), unname(inst)) || !identical(lock$R$Version, paste(R.version$major, R.version$minor, sep = ".")))
  stop("Installed packages differ from renv.lock: ", paste(PKG[ver != inst], collapse = ", "), call. = FALSE)
go_info <- GO.db::GO_dbInfo(); eg_info <- org.Mm.eg.db::org.Mm.eg_dbInfo()
day_month_year <- function(x) if (grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", x)) sprintf("%d %s %s", as.integer(substr(x, 9, 10)), month.abb[as.integer(substr(x, 6, 7))], substr(x, 1, 4)) else
  sub("^([0-9]{4})-([A-Za-z]{3})([0-9]{2})$", "\\3 \\2 \\1", x)   # "2025-07-22", "2025-Sep24" -> "22 Jul 2025", "24 Sep 2025"
GO_DATE <- day_month_year(go_info$value[go_info$name == "GOSOURCEDATE"]); EG_DATE <- day_month_year(eg_info$value[eg_info$name == "EGSOURCEDATE"])
stopifnot(grepl("^[0-9]{1,2} [A-Z][a-z]{2} [0-9]{4}$", c(GO_DATE, EG_DATE)))
complex_changed <- sum(rmod$complex_exception %in% TRUE & rmod$coverage < rules$mod_cov & rmod$rule_confidence == "moderate", na.rm = TRUE)
GO_MIN <- nets$go_min[1]; GO_MAX <- nets$go_max[1]
SMCUT <- nets |> filter(version == "original") |> transmute(t = sprintf("%s %.2f", tolower(lab_ds(dataset)), sm_cut)) |> pull(t) |> paste(collapse = ", ")
ARI_MIN <- min(nets$stab_ari)
n_of <- function(v, what) sum(rmod$version == v & rmod$signal_class == what)
cnt <- function(v) sprintf("%s: %d modules (single signal %d, two signals %d, several signals %d, unannotated (weak) %d, unannotated %d) and %d supermodules.",
                           paste(lab_c(v), "analysis"), sum(rmod$version == v), n_of(v, "single signal"), n_of(v, "two signals"), n_of(v, "several signals"),
                           n_of(v, "unannotated (weak)"), n_of(v, "unannotated"), sum(rsm$version == v))
nn <- function(v, d) nets$samples[nets$version == v & nets$dataset == d]
design_line <- sprintf("Design: %d male mice (%d control, %d resilient, %d susceptible); bilateral (left and right hemisphere) laser-microdissected region-layer units of the hippocampus in three compartments: neuropil (%d samples in the primary and %d in the sensitivity network), soma (%d) and microglia-enriched regions (%d).",
                       nets$n_animals[1], nets$n_con[1], nets$n_res[1], nets$n_sus[1], nn("original", "neuron_neuropil"), nn("new", "neuron_neuropil"), nn("original", "neuron_soma"), nn("original", "microglia"))
stopifnot(n_distinct(nets$n_animals) == 1, n_distinct(sub(";.*$", "", nets$groups)) == 1, nn("original", "neuron_soma") == nn("new", "neuron_soma"), nn("original", "microglia") == nn("new", "microglia"))
ex_mod <- function(cls, conf = NULL) {   # first primary module with that class (and confidence), as a worked example
  x <- mod_base |> filter(version == "original", signal_class == cls, is.null(conf) | rule_confidence %in% conf) |> slice(1)
  if (!nrow(x)) return(NULL)
  other <- as.integer(x$n_comparable) - 1L
  ev <- if (cls == "unannotated") sub("[.]$", "", coalesce(x$note, "no significant GO term")) else if (cls == "unannotated (weak)") sprintf("no signal passes; its significant terms form one sub-threshold signal (%s)", x$weak_association)
        else sprintf("dominant signal led by %s, largest term %s; %s; coverage %.0f%%, hub support %.0f%%", x$lead_txt, x$best_txt,
                     if (other == 0) "no other comparable signal" else if (other == 1) "one other comparable signal" else sprintf("%d other comparable signals", other), 100 * x$coverage, 100 * x$hub_support)
  sprintf("%s %s (%s; annotation confidence %s): %s. Label: '%s'.%s", lab_ds(x$dataset), short(x$ModuleID), cls, x$rule_confidence, ev, x$label,
          if (is.na(x$wording) || !nzchar(x$wording)) "" else paste0(" Words: ", x$wording, "."))
}
ex_sm <- sm_base |> filter(version == "original", rule_class %in% c("concordant", "compound")) |> slice(1)
ex_r8 <- r8 |> filter(grepl("^yes", rule8)) |> left_join(mlab, by = K) |> slice(1)
examples <- c(unlist(Filter(Negate(is.null), list(ex_mod("single signal", "high"), ex_mod("single signal", c("moderate", "low")), ex_mod("two signals"), ex_mod("several signals"),
                                                     ex_mod("unannotated (weak)"), ex_mod("unannotated")))),
  sprintf("Supermodule: primary %s %s (%s) joins %s. Label: '%s'.", tolower(lab_ds(ex_sm$dataset)), ex_sm$SupermoduleID, ex_sm$rule_class,
          with(mlab |> filter(version == "original", dataset == ex_sm$dataset, ModuleID %in% ids_of(gsub(";", ";", ex_sm$member_modules))), paste(sprintf("%s ('%s')", short(ModuleID), label), collapse = " and ")),
          ex_sm$label),
  sprintf("Same words in the sensitivity analysis (step 8): sensitivity %s %s continues %s and uses its words (%s). Label: '%s'.", tolower(lab_ds(ex_r8$dataset)), short(ex_r8$ModuleID),
          ex_r8$continues, sub("^yes: ", "", ex_r8$rule8), ex_r8$label))

# ----------------------------------------------------------------------------------- method text
how <- list(
  list(heading = "Overview", lines = c(
    "A label is a short description of what the proteins of one co-abundance module have in common in the Gene Ontology (GO). Labels come from each module's own GO over-representation results, by fixed rules. The rules decide whether a module is labelled, how many biological signals its label names, and how well GO describes it (annotation confidence). The words are then chosen from the GO terms the rules select, within fixed templates, and checked by script against the rules and the GO evidence.",
    "The same rules, thresholds and code were applied to all six networks: three compartments, each in the primary analysis (all-protein median centring) and the sensitivity analysis (complete-case median centring). No group, behavioural or physiological result was used to form a label.")),
  list(heading = "Definitions", lines = c(
    "Gene-mapped protein: a protein whose protein group resolves to exactly one Entrez Gene ID. GO counts count each gene once; protein groups that do not resolve to exactly one gene (several genes, or a member without an unambiguous gene annotation) are left unmapped and not tested.",
    sprintf("Significant term: a GO term with Benjamini-Hochberg-adjusted P value (q) < %.2f in the module.", rules$q),
    "Signal: a set of significant terms carried largely by the same module proteins (steps 2 and 3). A sub-threshold signal is a signal that does not pass the threshold (step 4).",
    "Leading term: the most significant term of a signal. Largest term: the term of a signal carried by most module proteins.",
    "Dominant signal: the passing signal whose largest term has most proteins.",
    "Coverage: the module proteins in the dominant signal's largest term, divided by the module's gene-mapped proteins.",
    sprintf("Hub support: the share of the module's %d gene-mapped proteins with the highest module membership (kME; one per gene) that carry any term of the dominant signal.", rules$hub_n))),
  list(heading = "Steps", lines = c(
    sprintf("1. GO over-representation. For every module, the gene-mapped proteins were tested for over-representation of GO terms with a one-sided hypergeometric test (clusterProfiler enrichGO), separately for biological process (BP), cellular component (CC) and molecular function (MF). The background was all gene-mapped proteins of that network annotated in the ontology (sheet Networks). Only terms annotated to %d to %d background genes were tested. P values were adjusted by Benjamini-Hochberg within each module and ontology, and q < %.2f counts as significant. No further correction across modules, ontologies or networks was applied: labels describe modules and are not tests of hypotheses. With Benjamini-Hochberg correction across all modules and ontologies of a network instead, %d of the %d terms named in labels keep q < %.2f; labels other than 'unannotated (weak)' also require more than %d proteins and significant terms in at least %d ontologies (step 4), while a weak label names a signal that fails this threshold. Annotation: org.Mm.eg.db %s (Entrez Gene, %s) and GO.db %s (GO release %s), all evidence codes. Every significant term of every module, with the proteins that carry it, is in sheet GO evidence.",
            GO_MIN, GO_MAX, rules$q, NET_KEEP, nrow(lt), rules$q, rules$min_proteins, rules$min_ontologies, ver[["org.Mm.eg.db"]], EG_DATE, ver[["GO.db"]], GO_DATE),
    sprintf("2. Grouping terms by shared proteins. The %d most significant BP terms of a module are clustered by how far their module proteins overlap: overlap coefficient |A and B| / min(|A|, |B|), average linkage, cut at overlap %.1f (the EnrichmentMap default). Nested terms, such as a process and its regulation or a complex and its subunits, therefore fall into one group.", rules$top_terms, rules$overlap),
    sprintf("3. Merging groups into signals. Groups are ranked by the size of their largest term (ties: the group whose leading term is more significant). Going down this list, a group is merged into the first signal already kept whose proteins it overlaps with an overlap coefficient of at least %.1f; otherwise it starts a new signal. Separate signals are therefore carried by largely different proteins. A merged signal keeps the most significant term as its leading term and the term with most proteins as its largest term. Finally, passing signals (step 4) are merged when each has at least %.0f%% of its proteins in the same significant CC term of the module (among its %d most significant CC terms); that CC term is recorded as the signal's cellular component (for example respiration and ATP synthesis in the mitochondrial inner membrane).", rules$overlap, 100 * rules$overlap, rules$top_terms),
    sprintf("4. Threshold. A signal passes when (a) the module has significant terms in at least %d of the three ontologies and (b) the signal's leading term is carried by more than %d module proteins. Condition (a) applies to the module, not to each signal, because BP and CC terms of the same biology often share too few proteins to fall into one signal. If no BP signal passes, steps 2 and 3 are repeated on the %d most significant terms of all three ontologies together; if that grouping has a passing signal, it classifies the module (a module defined by a location or a complex, such as microtubule or ER). Sheet Signals gives, for every signal, whether it passes and why not.", rules$min_ontologies, rules$min_proteins, rules$top_terms),
    sprintf("5. Signal class. The dominant signal is the passing signal with the largest largest term (ties: the more significant leading term). A passing signal is comparable when its largest term has at least %.0f%% as many proteins as the dominant one's. Classes: single signal (no other comparable signal), two signals (one other), several signals (two or more others). A module without a passing signal has its significant terms of all three ontologies grouped as in steps 2 and 3. If this gives exactly one signal, the module is 'unannotated (weak)' and the label names that sub-threshold signal. If it gives none, or several separate sub-threshold signals, the module is 'unannotated', because several weak signals cannot be summarised by one name. Sheet Modules notes, for each unannotated module, its most significant sub-threshold signal and why it does not pass.", 100 * rules$comparable_ratio),
    sprintf("6. Annotation confidence. This grades how well GO describes the module, not how robust the module is (robustness: step 10). Single signal: high when coverage >= %.0f%% and hub support >= %.0f%%; moderate when coverage >= %.0f%%, or when the dominant signal contains a term carried by at least %d module proteins that holds at least %.0f%% of the term's background proteins (a complex); otherwise low. Two signals: moderate by the same coverage or complex rule, otherwise low. Several signals and unannotated (weak): low. Unannotated: none. %s",
            100 * rules$high_cov, 100 * rules$hub_share, 100 * rules$mod_cov, rules$complex_n, 100 * rules$complex_share,
            if (complex_changed == 0) "In these six networks the complex rule did not change any module's confidence." else sprintf("The complex rule raised %d module(s) to moderate.", complex_changed)),
    "7. Wording of module labels. The words are chosen by hand within these templates: single signal, high confidence: 'X-enriched'; single signal, moderate or low: 'X-associated'; two signals: 'X- and Y-associated', dominant signal first; several signals: 'Several signals: X, Y, Z', the three largest comparable signals, largest first; unannotated (weak): 'unannotated (weak X association)'; unannotated: 'unannotated'.",
    "'enriched' and 'associated' grade annotation confidence only. Every named signal is over-represented (q < 0.05), so 'associated' does not mean 'not significant'. X is a GO term of that signal, chosen by hand: usually its leading or largest term; another term of the signal where that names its proteins more precisely, e.g. where the leading or largest term is broad ('small molecule metabolic process', 'protein transport') or vague ('neuron cellular homeostasis'), or where a more specific or a more general term of the signal is clearer ('mitochondrial ATP synthesis', 'protein catabolism'). When a signal holds a single term, that term is named even if it is broad; very general dominant terms carry a note. For every label, sheet Modules (How the words were chosen) gives the named term and the signal's leading and largest terms, so each choice can be checked. '/' joins further terms of the same signal where one term alone would misdescribe it ('RNA processing/splicing'). Shortening keeps the meaning, in these ways only: 'metabolic process' becomes 'metabolism', 'catabolic process' 'catabolism', 'biosynthetic process' 'biosynthesis'; ER stands for endoplasmic reticulum; an adjective may stand for its noun ('lysosomal' for 'lysosome'); words of a GO term may be left out or reordered ('ER stress response' for 'response to endoplasmic reticulum stress'), but no word is added except the signal's cellular component; no hyphen is added to GO's spelling; a process is never named after a structure.",
    "Every named term, with its GO ID, q and protein count, is listed in sheet Labels (Named GO terms), flagged in sheet GO evidence (Named in the label), and its choice explained in sheet Modules (How the words were chosen). Within one network no two module labels are the same, except 'unannotated'. A script checks every label: its form matches its class and confidence; each named term is a GO term of the signal it names, spelled as above; two- and several-signal labels name the comparable signals largest first; labels are unique within a network; supermodule labels name all their members.",
    sprintf("8. The same words in the sensitivity analysis. A sensitivity-analysis module that takes at least %.0f%% of its proteins from one primary module, and whose comparable signals contain that module's dominant signal (its leading term is one of their terms, or their term sets overlap with Jaccard >= %.1f), uses the primary module's words for the terms they share, provided those words name terms of its own signals; its other signals are named from its own GO. Sheets Labels and Modules show for every sensitivity module whether and why it uses the primary words; sheet Correspondence shows how modules of the two analyses overlap. Module numbers are not comparable between the analyses.", 100 * rules$carry_share, rules$term_jaccard),
    sprintf("9. Supermodules. Within each network, module eigengenes are clustered by average linkage on 1 - Pearson correlation and cut at a fixed height per compartment (%s), the same in both analyses: the middle of the widest gap between merge heights of the compartment's primary-analysis dendrogram within 0.35-0.65, rounded to 0.05 (a rule that uses the dendrogram only); sheet Networks gives the number of supermodules at other cut heights. Classes: singleton (one member; it keeps the member's confidence, and a weak or unannotated member makes it 'unannotated (weak)' or 'unannotated'); concordant (all members labelled, and every pair of members' dominant signals shares at least %.0f%% of its terms, Jaccard); compound (all members labelled, otherwise); mixed (labelled and unannotated members); unannotated (no labelled member). Supermodule labels are generated by script from the member labels, with the member IDs: singleton: the member's label, 'X-enriched (m05)', 'unannotated (weak X association; m05)' or 'unannotated (m05)'; concordant: the largest member's wording with all IDs and the suffix set by the supermodule's confidence, 'X-associated (m09 + m16)'; compound: 'Compound: X (mA) + Y (mB)', where a two-signal member contributes 'X and Y' and a several-signal member its first two signals; mixed: 'Mixed: X (mA) + unannotated member (mB)'; unannotated: 'unannotated (weak X (mA) and Y (mB) associations)', with members without any signal listed by ID after a semicolon, or 'unannotated (mA, mB)' when no member has a sub-threshold signal. Confidence: singleton = its member's; concordant and compound = the lowest member's; mixed = low; unannotated = low when a member is weak, otherwise none.", SMCUT, 100 * rules$term_jaccard),
    sprintf("10. Stability. Stability is reported next to each label and never used to form it. Each network was rebuilt 9 times, each time without all samples of one animal, with the network's soft power and tree-cut settings. The same procedure on all animals reproduced every network %s; rebuilds are used only when the adjusted Rand index is at least %.2f. A module counts as recovered in a rebuild when its best-matching rebuilt module has Jaccard >= %.1f, computed on the proteins present in both (sheet Stability). Module preservation statistics between groups (Zsummary) are not reported: the reference network contains the test samples, so they are not independent tests.",
            if (ARI_MIN == 1) "exactly (adjusted Rand index = 1)" else sprintf("(adjusted Rand index >= %.3f)", floor(1000 * ARI_MIN) / 1000), rules$rebuild_ari, rules$stable_jaccard),
    "11. What a label does not claim. A label names what a module's proteins share in GO. It does not claim a demonstrated function, a cell type of origin, a response to stress, or causality. Proteins measured in microglia-enriched regions need not come from microglia. 'ER stress response' is the GO process response to endoplasmic reticulum stress, not the social stress of the experiment.")),
  list(heading = "Worked examples (primary analysis)", lines = examples))
params <- tribble(~Parameter, ~Value, ~Purpose,
  "GO significance", sprintf("q < %.2f (BH within module and ontology)", rules$q), "Conventional false discovery rate for calling a term significant.",
  "GO term size", sprintf("%d to %d background genes", GO_MIN, GO_MAX), "Excludes terms too small to be stable and too broad to be informative.",
  "Terms grouped per module", sprintf("%d most significant", rules$top_terms), "Grouping uses the strongest terms; all significant terms remain in GO evidence.",
  "Grouping cut", sprintf("overlap coefficient %.1f", rules$overlap), "EnrichmentMap default for joining terms that share most of their genes.",
  "Merging groups", sprintf("overlap coefficient >= %.1f", rules$overlap), "Same cut as the grouping, so separate signals are carried by largely different proteins.",
  "Cellular-component merge", sprintf(">= %.0f%% of each signal's proteins in one CC term", 100 * rules$overlap), "Joins processes that take place in the same structure (e.g. respiration and ATP synthesis).",
  "Ontologies with significant terms", sprintf(">= %d of BP, CC, MF", rules$min_ontologies), "A passing signal needs support from more than one ontology.",
  "Proteins carrying the leading term", sprintf("> %d", rules$min_proteins), "A passing signal must rest on more than a handful of proteins.",
  "Comparable signal", sprintf(">= %.0f%% of the dominant signal's largest term", 100 * rules$comparable_ratio), "A second signal is named only when it is at least half the size of the dominant one.",
  "High confidence", sprintf("coverage >= %.0f%% and hub support >= %.0f%% of %d hubs", 100 * rules$high_cov, 100 * rules$hub_share, rules$hub_n), "The signal covers a substantial part of the module and of its most connected proteins.",
  "Moderate confidence", sprintf("coverage >= %.0f%%, or a term with >= %d module proteins holding >= %.0f%% of its background", 100 * rules$mod_cov, rules$complex_n, 100 * rules$complex_share), "The signal covers a smaller part of the module, or the module holds most of a protein complex.",
  "Same words across analyses", sprintf(">= %.0f%% of the sensitivity module's proteins from one primary module, and that module's dominant signal found again (its leading term among the comparable signals' terms, or term Jaccard >= %.1f)", 100 * rules$carry_share, rules$term_jaccard),
  "A module that continues a primary module keeps its words for the terms they share (step 8).",
  "Concordant supermodule", sprintf("dominant-signal term Jaccard >= %.1f for every member pair", rules$term_jaccard), "Members describe the same biology.",
  "Supermodule cut height", SMCUT, "Middle of the widest gap between merge heights of the primary-analysis eigengene dendrogram within 0.35-0.65, rounded to 0.05; the same in both analyses. Supermodule numbers at other heights: sheet Networks.",
