# ----------------------------------------------------------------------------------- workbook
text_sheet <- function(wb, sheet, title, blocks) {   # same layout as the Read me sheet
  addWorksheet(wb, sheet); r <- 1
  writeData(wb, sheet, title, startRow = r); addStyle(wb, sheet, TITLE, rows = r, cols = 1); r <- r + 2
  body <- createStyle(fontName = "Arial", fontSize = 11, wrapText = TRUE, valign = "top")
  for (b in blocks) {
    writeData(wb, sheet, b$heading, startRow = r); addStyle(wb, sheet, SUB, rows = r, cols = 1); r <- r + 1
    writeData(wb, sheet, data.frame(x = b$lines), startRow = r, colNames = FALSE)
    addStyle(wb, sheet, body, rows = r:(r + length(b$lines) - 1), cols = 1, gridExpand = TRUE); r <- r + length(b$lines) + 1
  }
  setColWidths(wb, sheet, cols = 1, widths = 150); showGridLines(wb, sheet, FALSE)
}
NUM <- list(int = character(), d1 = character(), d2 = character(), d3 = character(), sci = character())
put <- function(sheet, df, freeze = 4, ints = character(), d1 = character(), d2 = character(), d3 = character(), sci = character(), wide = character(), wrap = character(), long = character(),
                label = character()) {   # label: a wrapped text column of medium width
  ci <- function(nm) { i <- match(nm, names(df)); stopifnot(!anyNA(i)); i }
  num <- c(ints, d1, d2, d3, sci)
  fit <- function(n) max(10, min(30, max(nchar(n) * 0.9, max(c(0, nchar(as.character(df[[n]]))), na.rm = TRUE) + 2)))   # short text columns: fit header and values
  w <- vapply(names(df), function(n) if (n %in% long) 100 else if (n %in% wide) 70 else if (n %in% label) 45 else if (n %in% wrap) 40 else if (n %in% num) max(10, min(14, nchar(n) / 2)) else fit(n), numeric(1))
  put_table(wb, sheet, df, int_cols = ci(ints), left_cols = which(!names(df) %in% num), widths = unname(w), freeze_col = freeze)
  rows <- 2:(nrow(df) + 1)
  for (st in list(list(d1, D1), list(d2, D2), list(d3, D3), list(sci, SCI))) if (length(st[[1]])) addStyle(wb, sheet, st[[2]], rows = rows, cols = ci(st[[1]]), gridExpand = TRUE, stack = TRUE)
  if (length(c(wide, wrap, label))) addStyle(wb, sheet, WRAP, rows = rows, cols = ci(c(wide, wrap, label)), gridExpand = TRUE, stack = TRUE)
}
