conditionalFormatting(wb, "Stability", cols = which(grepl("^without ", names(stability))), rows = 2:(nrow(stability) + 1), rule = sprintf(">=%s", rules$stable_jaccard), style = HI)
put("Correspondence", corr, freeze = 3, ints = "Shared proteins", d1 = c("Share of primary module (%)", "Share of sensitivity module (%)"), d2 = "Jaccard", wide = c("Primary label", "Sensitivity label"))
put("Figure 3 exemplars", fig3, freeze = 4, ints = c("Exemplar term: module proteins with term", "Exemplar term: BP-annotated module proteins", "Stability: recovered in (of 9)"),
    d1 = "Exemplar term: fold enrichment", sci = "Exemplar term: q in module", wide = c("Label", "How the module was chosen", "Note for readers"), wrap = c("Exemplar GO term", "Region of the exemplar (Figure 3)"))
put("Column guide", guide, freeze = 3, wide = "Meaning")
worksheetOrder(wb) <- match(c("Read me", "Labels", "Label counts", "How labels are formed", "Labelling parameters", "Networks", "Software and annotation", "Modules", "Supermodules",
                              "Signals", "GO evidence", "Proteins", "Stability", "Correspondence", "Figure 3 exemplars", "Column guide"), names(wb))
# the supplement holds no internal history: no dates, paths or previous wordings
txt <- c(unlist(how), unlist(lapply(SHEETS, function(d) unlist(lapply(d, as.character)))))
bad <- grep("20[0-9]{2}-[0-9]{2}-[0-9]{2}|[A-Z]:/|tools/|worktree|archive|Exp9|original-centring|complete-case network", txt, value = TRUE)
if (length(bad)) stop("Internal material in the reader-facing workbook: ", paste(head(unique(bad), 5), collapse = " || "), call. = FALSE)
f <- file.path(OUT, "Proteomics_WGCNA_module_labels.xlsx")
saveWorkbook(wb, f, overwrite = TRUE)

# internal: the label history (not for the supplement)
wh <- createWorkbook()
add_readme(wh, "WGCNA label history (internal; not part of the supplement)", list(list(heading = "What this file is", lines = c(
  "Every label that differs from the labels of 2026-10-22, with the previous and the current wording and the reason: corrections after the check of all labels against their evidence (2026-10-23), the regeneration on the official gene mapping with GO term sizes 10-800 (2026-10-24/26), the label check of 2026-10-26 and the supermodule cut-height rule of 2026-10-26 (supermodules matched by their members; merged ones list the earlier supermodules they join). Source: annotation_review/label_changes_2026-10-23.csv, written by derive_supermodule_labels.R."))))
put_table(wh, "Label history", chg |> ord() |> transmute(Analysis = lab_c(version), Compartment = lab_ds(dataset), Level = level, ID = short(entity_id),
  `ID until 2026-10-22` = short(previous_entity_id), `Label until 2026-10-22` = previous_label, `Current label` = new_label, Why = reason),
  widths = c(30, 18, 12, 9, 14, 50, 50, 90), freeze_col = 6, left_cols = 1:8)
saveWorkbook(wh, file.path(OUT, "Proteomics_WGCNA_label_history.xlsx"), overwrite = TRUE)
cat("written:", f, "| labels", nrow(labels_sheet), "| modules", nrow(modules), "| supermodules", nrow(supermodules), "| signals", nrow(signals), "| GO rows", nrow(go_tab),
    "| proteins", nrow(proteins), "| stability", nrow(stability), "| column guide", nrow(guide), "| history", nrow(chg), "\n")
